UPDATE lgcom_approval_status_n lasn
SET    lasn.approval_date = DECODE(lasn.approval_date,NULL,sysdate,lasn.approval_date)
      ,lasn.share_flag = 'Y'
      ,lasn.approval_status_code = '3'
WHERE lasn.request_master_id = #{requestMasterId}
AND   lasn.request_code = #{requestCode}
AND   lasn.user_no =  #{USER_SESSION.userName}
AND   lasn.approval_action_code in ('REFERENCE', 'FORWARD')
AND   lasn.approval_status_code = '2'
AND   lasn.approval_date is null
